def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(val, default=(0, 0)):
        if isinstance(val, (list, tuple)) and len(val) >= 2:
            return val[0], val[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    env = observation.get("environment_name", "resource_collection")

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        candidates = []
        for k in ("opponent_position", "opponent", "pursuer_position", "enemy_position"):
            p = pos(observation.get(k), None)
            if p is not None:
                candidates.append(p)
        if not candidates:
            candidates = [opp_pos]
        grid_w = observation.get("grid_width", 0)
        grid_h = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, grid_h - 1)), (max(0, grid_w - 1), 0), (max(0, grid_w - 1), max(0, grid_h - 1))]
        target = max(corners, key=lambda c: min(dist(c, p) for p in candidates))
        return step_toward(self_pos, target)

    if env == "territory_control":
        pools = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "targets", "cells_to_claim"):
            cells = observation.get(key) or []
            if cells:
                pools.extend(cells)
        if pools:
            best = min(pools, key=lambda item: dist(self_pos, pos(item)))
            return step_toward(self_pos, pos(best))
        grid_w = observation.get("grid_width", 0)
        grid_h = observation.get("grid_height", 0)
        center = (grid_w // 2, grid_h // 2)
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = min(resources, key=lambda item: dist(self_pos, pos(item)))
        target = pos(best)
        if dist(self_pos, opp_pos) <= 1 and dist(target, opp_pos) < dist(self_pos, opp_pos):
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

    if dist(self_pos, opp_pos) <= 1:
        return step_away(self_pos, opp_pos)

    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)
    center = (grid_w // 2, grid_h // 2)
    if grid_w and grid_h:
        return step_toward(self_pos, center)
    return [0, 0]

